<template>
  <div v-if="showRewards" class="reward-overlay">
    
    <div class="reward-wrapper">

      <h2 class="reward-title">戰鬥勝利！請選擇獎勵</h2>

      <div class="reward-box">
        <div 
          v-for="(r, index) in rewards" 
          :key="r.id + index" 
          class="reward-container"
          :class="{ 
            selected: selectedIndex === index, 
            disappear: selectedIndex !== null && selectedIndex !== index,
            'is-card': r.type === 'card'
          }"
          @click="onChoose(index)"
        >
          
          <template v-if="r.type === 'card' && r.cardData">
            <GameCard 
              :card="r.cardData" 
              class="pointer-events-none scale-110" 
            />
          </template>

          <div v-else class="reward-content">
            <div class="text-4xl mb-2">
               <span v-if="r.type === 'money'">💰</span>
               <span v-else-if="r.type === 'item'">🧪</span>
               <span v-else>🎁</span>
            </div>
            <div class="text-xl font-bold">{{ r.name }}</div>
            <div class="text-sm mt-1 text-gray-100" v-if="r.amount">x {{ r.amount }}</div>
          </div>

        </div>
      </div>
      </div>
  </div>
</template>

<script>
import GameCard from "./Card.vue";

export default {
  components: { GameCard },
  props: {
    rewards: Array,
    showRewards: Boolean
  },
  data() {
    return {
      selectedIndex: null
    }
  },
  methods: {
    onChoose(index) {
      if (this.selectedIndex !== null) return;

      this.selectedIndex = index;
      const reward = this.rewards[index];

      this.$el.querySelectorAll(".reward-container").forEach((r) => {
         r.classList.add("no-hover");
      });

      this.$emit('selected', reward);

      setTimeout(() => {
        this.$emit('close');
        this.selectedIndex = null; 
        this.$el.querySelectorAll(".reward-container").forEach(r => r.classList.remove("no-hover"));
      }, 600);
    }
  }
}
</script>

<style scoped>
/* 遮罩 */
.reward-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
}

/* 垂直容器 */
.reward-wrapper {
  display: flex;
  flex-direction: column; 
  align-items: center;    
  gap: 40px;           
}

/* 標題樣式  */
.reward-title {
  font-size: 32px;
  font-weight: bold;
  color: #fbbf24; 
  text-shadow: 0 0 10px rgba(251, 191, 36, 0.5);
  letter-spacing: 2px;
}

/* 獎勵列表容器：負責橫向排列 */
.reward-box {
  display: flex;
  gap: 150px; /* 獎勵之間的間距 */
  justify-content: center;
  align-items: center;
}

.reward-container {
  width: 160px;
  height: 230px;
  transition: transform 0.6s ease, opacity 0.6s ease;
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}

.reward-container.is-card {
  background: transparent;
  box-shadow: none;
  border: none;
}

.reward-container:not(.is-card) .reward-content {
  width: 100%;
  height: 100%;
  padding: 10px;
  background: linear-gradient(#ffe066, #ffbd2e);
  border: 3px solid #d4a017;
  box-shadow: 0 4px 10px rgba(0,0,0,0.3);
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  color: #5c410a;
}

.reward-container:not(.no-hover):hover {
  transform: translateY(-20px) scale(1.5);
  z-index: 10;
}

.reward-container.selected {
  transform: translateY(-120px) scale(1.5);
  opacity: 0;
  z-index: 20;
}

.reward-container.disappear {
  transform: translateY(50px) scale(0.8);
  opacity: 0;
}
</style>