<template>
  <div class="event-overlay">
    <div class="event-box">
      <h2 class="event-title">請選擇事件</h2>

      <div class="event-cards">
        <div
          v-for="event in randomEvents"
          :key="event.id"
          class="event-card"
          @click="choose(event)"
        >
          <img v-if="event.img" :src="event.img" class="event-img" />
          <div v-else class="event-img-placeholder">?</div>
          
          <div class="event-name">{{ event.name }}</div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "ExpeditionEvent",

  props: {
    events: Object,
  },

  data() {
    return {
      randomEvents: [] 
    };
  },

  mounted() {
    // 每次元件顯示時，執行隨機挑選
    this.pickRandomEvents();
  },

  methods: {
    pickRandomEvents() {
      if (!this.events) return;

      const allEvents = Object.values(this.events);

      const shuffled = allEvents.sort(() => Math.random() - 0.5);

      this.randomEvents = shuffled.slice(0, 3);
    },

    choose(event) {
      this.$emit("choose", event);
    },
  },
};
</script>

<style scoped>
/* 增加一個圖片佔位符樣式，以防事件沒有圖片 */
.event-img-placeholder {
  width: 100%;
  height: 400px; 
  background: #333;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
  color: #555;
  border-radius: 6px;
}

/* --- 以下保持原本的樣式 --- */

/* 背景遮罩 */
.event-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 2000;
}

/* 中央容器 */
.event-box {
  text-align: center;
  padding: 20px;
  color: #ddd;
}

.event-title {
  font-size: 26px;
  margin-bottom: 20px;
}

/* 卡片容器 */
.event-cards {
  display: flex;
  gap: 150px;
  justify-content: center;
}

/* 卡片 */
.event-card {
  width: 220px;
  height: 380px;
  background: #1c1c1c;
  border: 2px solid #4a4a4a;
  border-radius: 8px;
  transition: 0.25s;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

/* hover 效果 */
.event-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 0 20px rgba(0, 190, 255, 0.6);
  border-color: #00d0ff;
}

/* 卡片圖片 */
.event-img {
  width: 100%;
  height: auto; 
  max-height: 400px;
  object-fit: cover;
  border-radius: 6px;
}

/* 標題 */
.event-name {
  font-size: 20px;
  padding: 12px;

  /* 地下城感：深色 + 立體邊框 */
  background: #1b1b1b;               
  color: #e0d8c3;                  
  border: 3px solid #3a2f22;           
  border-radius: 8px;              

  /* 金屬質感外框效果 */
  box-shadow:
    0 0 8px #000 inset,           
    0 0 12px rgba(0,0,0,0.6),    
    0 0 2px #6b5433 inset;             

  /* 仿地下城微微亮邊 */
  outline: 2px groove #5c462f;
}
</style>