<template>
  <div class="card" @click="handleClick">
    <img :src="item.img" class="card-bg" :alt="item.name" />

    <div class="card-content">
      
      <div class="card-text-name">
        {{ item.name }}
      </div>

      <div class="card-text-count">
        x{{ count }}
      </div>

      <div class="card-text-desc">
        {{ item.desc }}
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "ItemCard",
  props: {
    item: {
      type: Object,
      required: true
    },
    count: {
      type: Number,
      default: 1
    }
  },
  methods: {
    handleClick() {
      // 點擊時觸發 use 事件，傳回該道具
      this.$emit('use', this.item);
    }
  }
};
</script>

<style scoped>
/* 繼承 Card.vue 的樣式 */
.card {
  width: 150px;
  height: 220px;
  position: relative;
  cursor: pointer;
  transition: transform 0.2s;
  user-select: none;
  background-color: transparent;
  border-radius: 15px;
  overflow: hidden;
  /* 增加一點陰影讓它看起來像卡牌 */
  box-shadow: 0 4px 6px rgba(0,0,0,0.3);
}

.card:hover {
  transform: scale(1.1);
  z-index: 100;
}

.card-bg {
  width: 100%;
  height: 100%;
  object-fit: cover; /* 道具圖通常是滿版，可用 cover 或 contain */
  pointer-events: none;
}

.card-content {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

/* 名稱位置 */
.card-text-name {
  position: absolute;
  top: 1%; 
  width: 100%;
  text-align: center;
  font-size: 15px;
  font-weight: bold;
  color: #fff;
  text-shadow: 2px 2px 0 #000;
  padding: 0 5px;
}

/* 數量位置 (左下角，模仿費用位置) */
.card-text-count {
  position: absolute;
  bottom: 1%;    
  right: 5%;       
  font-size: 20px;
  font-weight: 900;
  color: #fbbf24; /* 金黃色 */
  text-shadow: 0 0 4px #000, 2px 2px 0 #000;
}

/* 描述位置 (最下方) */
.card-text-desc {
  position: absolute;
  bottom: 3%;
  left: 16%;
  width: 70%;
  height: 20%;
  font-size: 11px;
  color: #eee;
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1.3;
  text-shadow: 1px 1px 0 #000;
  border-radius: 4px;
}
</style>