//enemy.js

import { applyCardEffect } from "./applyCardEffect.js";

export async function enemyAI(player, enemy, logFn, onHit) {
    
    // ... 前面的 getCardScore 函數保持不變 ...
    const getCardScore = (card) => {
        const enoughAP = !card.costAP || enemy.ap >= card.costAP;
        const enoughMP = !card.costMP || enemy.mp >= card.costMP;
        if (!enoughAP || !enoughMP) return 0;

        let score = 0;
        const hpPercent = enemy.hp / enemy.maxHP;

        if (card.type === "heal") {
            if (hpPercent >= 1.0) return 0;
            if (hpPercent < 0.3) score = 100;
            else if (hpPercent < 0.6) score = 80;
            else score = 40;
        } 
        else if (card.type === "defend" || card.type.endsWith("_defend")) {
            if (enemy.defend > 20) score = 10;
            else if (hpPercent < 0.5) score = 90;
            else score = 50;
        } 
        else if (card.type === "buff_attack") {
            if (enemy.atk > enemy.baseAtk + 5) score = 5;
            else score = 70;
        } 
        else if (card.type === "attack" || card.type.endsWith("_attack")) {
            if (card.damage && player.hp <= card.damage) score = 999;
            else score = 60;
        } 
        else {
            score = 30;
        }
        return score;
    };

    // --- 修改這裡：使用變數控制迴圈 ---
    let keepActing = true; // 控制旗標

    while (keepActing) {
        //  給手牌裡每一張牌打分
        const candidates = enemy.hand.map((card, index) => ({
            card,
            index,
            score: getCardScore(card)
        }));

        //  過濾並排序
        const playableCards = candidates
            .filter(c => c.score > 0)
            .sort((a, b) => b.score - a.score);

        //  檢查是否有牌可打
        if (playableCards.length === 0) {
            keepActing = false; // 設定為 false，迴圈將在這次結束後停止
            // 這裡不需要 break，因為 if else 會讓程式跑到迴圈底部自然判斷 false 結束
        } else {
            //  有牌打，取出最高分的那張
            const bestCandidate = playableCards[0];
            const cardToPlay = bestCandidate.card;

            //  從手牌移除
            enemy.hand.splice(bestCandidate.index, 1);

            //  執行效果
            logFn(`${enemy.name} 使用卡牌: ${cardToPlay.name}`);
            applyCardEffect(enemy, player, cardToPlay, logFn, onHit);

            enemy.discard.push(cardToPlay); 

            //  暫停
            await sleep(800);
            
            // 迴圈繼續，keepActing 依然是 true
        }
    }

    // --- 回合結束棄牌階段 ---
    while (enemy.hand.length > 0) {
        const card = enemy.hand.pop();
        enemy.discard.push(card);
    }
}

function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}
