<template>
  <div class="card equip-card" @click="handleClick">
    <img :src="equip.img" class="card-bg" :alt="equip.name" />

    <div class="card-content">
      <div class="card-text-name">
        {{ equip.name }}
      </div>

      <div class="card-text-desc">
        {{ equip.desc }}
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "EquipCard",
  props: {
    equip: {
      type: Object,
      required: true
    }
  },
  methods: {
    handleClick() {
      this.$emit('buy', this.equip);
    }
  }
};
</script>

