  position: relative;
  cursor: pointer;
  transition: transform 0.2s;
  user-select: none;
  background-color: transparent;
  border-radius: 15px;
  overflow: hidden;
  box-shadow: 0 4px 6px rgba(0,0,0,0.3);
}

.card:hover {
  transform: scale(1.1);
  z-index: 100;
}

.card-bg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
}

.card-content {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

.card-text-name {
  position: absolute;
